<?php use App\Core\Money; ?>
<!doctype html><html><head><meta charset="utf-8"><title><?= e($doc['doc_no'] ?? 'Document') ?> · Quantum Nexis LLC</title><style>body{font:14px Arial;color:#111;max-width:900px;margin:30px auto}h1{color:#075985}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.box{border:1px solid #ddd;padding:16px}@media print{.no-print{display:none}body{margin:0}}</style></head><body><button class="no-print" onclick="print()">Print</button><h1><?php if(!empty($settings['company_logo_url'])):?><img src="<?=e($settings['company_logo_url'])?>" style="max-height:62px;max-width:240px;vertical-align:middle"><br><?php endif;?><?= e($settings['company_name']??'Quantum Nexis LLC') ?></h1><p><?= e($office['address']??'') ?> · <?= e($office['phone']??'') ?> · <?= e($settings['admin_email']??'') ?></p><hr><h2><?= e(ucwords(str_replace('_',' ',$doc['doc_type']??''))) ?> <?= e($doc['doc_no']??'') ?></h2><div class="box"><b>Customer:</b> <?= e($doc['customer']['company_name']??'') ?><br><?= e($doc['customer']['email']??'') ?><br><b>Date:</b> <?= e($doc['issue_date']??'') ?></div><table><tr><th>Description</th><th>Qty</th><th>Unit</th><th class="right">Total</th></tr><?php foreach(($doc['items']??[]) as $i): ?><tr><td><?= e($i['description']) ?></td><td><?= e($i['qty']) ?></td><td><?= e(Money::format((int)$i['unit_price_minor'],$doc['currency'])) ?></td><td class="right"><?= e(Money::format((int)$i['line_total_minor'],$doc['currency'])) ?></td></tr><?php endforeach; ?></table><?php if(!empty($settings['payment_link'])):?><div style="float:right;text-align:center"><img alt="Payment QR" width="130" height="130" src="https://api.qrserver.com/v1/create-qr-code/?size=130x130&data=<?=rawurlencode($settings['payment_link'])?>"><br><small>Scan to pay</small></div><?php endif;?><h2 class="right">Total: <?= e(Money::format((int)$doc['total_minor'],$doc['currency'])) ?></h2></body></html>
